-- Enrichment program backend (C1 follow-up).
--
-- The enrichment calendar was rendered from a hard-coded client-side seed array
-- (SEED_ENRICHMENT_EVENTS). This makes enrichment_events the real backend:
--   * scope = 'global'   → enterprise-mandated events, apply to ALL resorts (location_id null)
--   * scope = 'location' → a resort's own event (location_id set)
-- Editing is restricted to the enterprise-admin grouping (lite enterprise_admin OR
-- profiles owner); everyone else gets read-only. The hard-coded starter calendar
-- is imported below as global events.

alter table public.enrichment_events add column if not exists scope text not null default 'location';
alter table public.enrichment_events alter column location_id drop not null;

do $$
begin
  if not exists (select 1 from pg_constraint where conname='enrichment_events_scope_chk') then
    alter table public.enrichment_events add constraint enrichment_events_scope_chk check (scope in ('global','location'));
  end if;
  if not exists (select 1 from pg_constraint where conname='enrichment_events_scope_location_chk') then
    alter table public.enrichment_events add constraint enrichment_events_scope_location_chk
      check ((scope='global' and location_id is null) or (scope='location' and location_id is not null));
  end if;
end $$;

create unique index if not exists enrichment_events_global_legacy_uidx
  on public.enrichment_events (legacy_source_id) where scope='global' and legacy_source_id is not null;
create index if not exists enrichment_events_scope_date_idx
  on public.enrichment_events (scope, event_date);

-- ── RLS ──────────────────────────────────────────────────────────────────
drop policy if exists enrichment_events_select on public.enrichment_events;
create policy enrichment_events_select on public.enrichment_events for select to authenticated
using (
  scope = 'global'
  or exists (select 1 from public.lite_profiles lp
             where lp.user_id = (select auth.uid()) and lp.is_active
               and (lp.location_id = enrichment_events.location_id or lp.role = 'enterprise_admin'::lite_role))
  or exists (select 1 from public.profiles p
             where p.id = (select auth.uid()) and p.role in ('owner','role_owner'))
);

-- Writes: enterprise-admin grouping only (lite enterprise_admin OR profiles owner).
drop policy if exists enrichment_events_insert on public.enrichment_events;
create policy enrichment_events_insert on public.enrichment_events for insert to authenticated
with check (
  exists (select 1 from public.lite_profiles lp where lp.user_id = (select auth.uid()) and lp.is_active and lp.role = 'enterprise_admin'::lite_role)
  or exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.role in ('owner','role_owner'))
);

drop policy if exists enrichment_events_update on public.enrichment_events;
create policy enrichment_events_update on public.enrichment_events for update to authenticated
using (
  exists (select 1 from public.lite_profiles lp where lp.user_id = (select auth.uid()) and lp.is_active and lp.role = 'enterprise_admin'::lite_role)
  or exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.role in ('owner','role_owner'))
)
with check (
  exists (select 1 from public.lite_profiles lp where lp.user_id = (select auth.uid()) and lp.is_active and lp.role = 'enterprise_admin'::lite_role)
  or exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.role in ('owner','role_owner'))
);

drop policy if exists enrichment_events_delete on public.enrichment_events;
create policy enrichment_events_delete on public.enrichment_events for delete to authenticated
using (
  exists (select 1 from public.lite_profiles lp where lp.user_id = (select auth.uid()) and lp.is_active and lp.role = 'enterprise_admin'::lite_role)
  or exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.role in ('owner','role_owner'))
);

